import Foundation

// The same loop as CaptionImporter.text(of:), line 144.
func decode(_ data: Data) -> (String, String.Encoding)? {
    for encoding in [String.Encoding.utf8, .utf16, .windowsCP1252, .isoLatin1] {
        if let text = String(data: data, encoding: encoding) { return (text, encoding) }
    }
    return nil
}

func srt(cues: Int, line: String) -> String {
    var s = ""
    for i in 1...cues {
        s += "\(i)\n00:00:0\(i % 10),000 --> 00:00:0\(i % 10),900\n\(line) \(i)\n\n"
    }
    return s
}

func name(_ e: String.Encoding) -> String {
    switch e {
    case .utf8: return "utf8"
    case .utf16: return "utf16"
    case .windowsCP1252: return "cp1252"
    case .isoLatin1: return "latin1"
    default: return "\(e)"
    }
}

var tally: [String: Int] = [:]
func run(_ label: String, _ data: Data) {
    guard let (text, enc) = decode(data) else {
        tally["\(label): nil", default: 0] += 1
        return
    }
    let arrow = text.contains("-->")
    tally["\(label): \(name(enc)) arrow=\(arrow)", default: 0] += 1
}

let lines = ["Café déjà vu", "El niño está aquí", "Über Straße größer", "Ça va très bien", "“Smart quotes” — dash"]
for cues in 1...9 {
    for line in lines {
        for pad in ["", "x", "xy"] {
            let text = srt(cues: cues, line: line + pad)
            if let d = text.data(using: .windowsCP1252) { run("cp1252 LF", d) }
            if let d = text.replacingOccurrences(of: "\n", with: "\r\n").data(using: .windowsCP1252) { run("cp1252 CRLF", d) }
            if let d = text.data(using: .isoLatin1) { run("latin1 LF", d) }
            run("utf8", text.data(using: .utf8)!)
            if let d = text.data(using: .utf16LittleEndian) { run("utf16le noBOM", d) }
            if let d = text.data(using: .utf16BigEndian) { run("utf16be noBOM", d) }
            run("utf16 BOM", text.data(using: .utf16)!)
            let ascii = text.folding(options: .diacriticInsensitive, locale: nil)
                .replacingOccurrences(of: "“", with: "\"").replacingOccurrences(of: "”", with: "\"")
                .replacingOccurrences(of: "—", with: "-").replacingOccurrences(of: "ß", with: "ss")
            if let d = ascii.data(using: .ascii) { run("ascii", d) }
        }
    }
}
