import Foundation

// The same loop as CaptionImporter.text(of:), line 144.
func decode(_ data: Data) -> (String, String.Encoding)? {
    for encoding in [String.Encoding.utf8, .utf16, .windowsCP1252, .isoLatin1] {
        if let text = String(data: data, encoding: encoding) { return (text, encoding) }
    }
    return nil
}

func name(_ e: String.Encoding) -> String {
    switch e {
    case .utf8: return "utf8"
    case .utf16: return "utf16"
    case .windowsCP1252: return "cp1252"
    case .isoLatin1: return "latin1"
    default: return "\(e)"
    }
}

func stamp(_ i: Int) -> String {
    let a = i * 3
    func t(_ s: Int, _ ms: Int) -> String {
        String(format: "%02d:%02d:%02d,%03d", s / 3600, s / 60 % 60, s % 60, ms)
    }
    return "\(t(a, 120)) --> \(t(a + 2, 480))"
}

let texts: [(String, [String])] = [
    ("french", ["Il a été très déçu ce matin.", "Où es-tu allé, mon frère ?", "Ça coûte à peu près dix euros."]),
    ("spanish", ["El niño está aquí, señor.", "¿Qué pasó después de la canción?", "Mañana iré a la montaña."]),
    ("italian", ["Perché non è più qui?", "Città e università, così è.", "Sarà già lì."]),
    ("german", ["Die Straße ist sehr groß.", "Wir müssen heute früh los.", "Das schöne Mädchen weiß es."]),
    ("german-no-eszett", ["Wir müssen heute früh los.", "Das schöne Mädchen kommt.", "Für dich und für mich."]),
    ("danish", ["Vi så en ørn over søen.", "Økonomien er blevet bedre.", "Hun går på gaden."]),
]

for (label, lines) in texts {
    var results: [String: Int] = [:]
    for cues in [1, 2, 3, 5, 10, 30, 100, 300, 1000] {
        for crlf in [false, true] {
            var s = ""
            for i in 1...cues {
                s += "\(i)\n\(stamp(i))\n\(lines[i % lines.count])\n\n"
            }
            if crlf { s = s.replacingOccurrences(of: "\n", with: "\r\n") }
            guard let d = s.data(using: .windowsCP1252), let (text, enc) = decode(d) else { continue }
            let key = "cues=\(cues)"
            if enc == .utf16 && !text.contains("-->") {
                results[key, default: 0] += 0
            } else {
                results[key, default: 0] += 1
            }
            _ = name(enc)
        }
    }
    let ordered = results.sorted { Int($0.key.dropFirst(5))! < Int($1.key.dropFirst(5))! }
    print(label, ordered.map { "\($0.key):\($0.value)/2" }.joined(separator: " "))
}

